import React, { Component } from 'react';
import logo from './logo.svg';
import './App.css';
import getApiResult from './JiraUtils';
import { AgGridReact } from 'ag-grid-react';
//import 'ag-grid/dist/styles/ag-grid.css';
//import 'ag-grid/dist/styles/ag-theme-balham.css';
import 'ag-grid-enterprise';

class AgGrid1 extends Component {
    constructor(props) {
        super(props);

        this.state = {
    columnDefs: [
        {headerName: "Make", field: "make", rowGroupIndex: 0 },
        {headerName: "Price", field: "price"}
    ],
    autoGroupColumnDef: {
        headerName: "Model",
        field: "model",
        cellRenderer:'agGroupCellRenderer',
        cellRendererParams: {
            checkbox: true
        }
    },
            rowData: [
                {make: "Toyota", model: "Celica", price: 35000},
                {make: "Ford", model: "Mondeo", price: 32000},
                {make: "Porsche", model: "Boxter", price: 72000}
            ]
        }
    }

	componentDidMount() {
		console.log('beginning mounted');

		getApiResult('https://api.myjson.com/bins/ly7d1','GET',null)
		    .then(function(res){
				   console.log("got result");
				   //this.setState({rowData:[]});
				   return res;
				})
			.then(rowData => this.setState({rowData}))
		//
		// fetch('https://api.myjson.com/bins/15psn9')
		//   .then(result => result.json())
		//   .then(rowData => this.setState({rowData}))
	}


    render() {
        return (
                <div
                  className="ag-theme-balham"
                  style={{
	                height: '800px',
	                width: '600px' }}
		            >
		            <button onClick={this.onButtonClick}>Get selected rows</button>
                    <AgGridReact
                    onGridReady={ params => this.gridApi = params.api }
                    enableSorting={true}
                    enableFilter={true}
                    rowSelection="multiple"
                        columnDefs={this.state.columnDefs}
                        groupSelectsChildren={true}
						autoGroupColumnDef={this.state.autoGroupColumnDef}
                        rowData={this.state.rowData}>
                    </AgGridReact>
                </div>
            );
    }

    onButtonClick = e => {
		debugger;
	    const selectedNodes = this.gridApi.getSelectedNodes()
	    const selectedData = selectedNodes.map( node => node.data )
	    const selectedDataStringPresentation = selectedData.map( node => node.make + ' ' + node.model).join(', ')
	    alert(`Selected nodes: ${selectedDataStringPresentation}`)
	}
}

export default AgGrid1;


