var $ = require('jquery');

function getApiResult(url, method, payload) {

   console.log('calling api for: ' + url);

   return new Promise(function(resolve, reject) {
	    $.ajax({
	             url: url,
	             type: method,
	             data: payload,
	             dataType: 'json',
	             success: function(res) {
	                 console.log(res);
	                 //this needs to be a promise....
	                 return resolve(res);
	             },
	             error: function(req,e) {
					 reject(e);
				 }
        });
   })
}

export default getApiResult;


